	if err != nil {
		return fmt.Errorf("init-agents: %w", err)
	}
	claudeInfo, err := inspectInstructionFile(repoRoot, claudeName, claudePath)
	if err != nil {
		return fmt.Errorf("init-agents: %w", err)
	}

